package org.synqoria.scheduling;
import org.synqoria.security.TrustedAccessContext;import java.time.*;import java.util.*;
public class AppointmentRequestIntakeTest {public static void main(String[] args){int n=0;var t=UUID.randomUUID();var f=UUID.randomUUID();var p=UUID.randomUUID();var r=UUID.randomUUID();var now=Instant.parse("2026-11-01T00:00:00Z");var w=new AppointmentWindow(now.plusSeconds(3600),now.plusSeconds(5400),ZoneId.of("Africa/Douala"));var c=new TrustedAccessContext(t,f,UUID.randomUUID(),Set.of("appointment:request"),Set.of(p));var s=new AppointmentRequestIntake();var d=s.prepare(c,UUID.randomUUID(),p,r,w,now);check(d.outcome()==AppointmentRequestIntake.Outcome.READY_FOR_RESTRICTED_TRANSACTION);n++;check(d.draft().state()==AppointmentAggregate.State.REQUESTED);n++;check(d.draft().tenant().equals(t));n++;check(s.prepare(c,UUID.randomUUID(),UUID.randomUUID(),r,w,now).draft()==null);n++;check(s.prepare(new TrustedAccessContext(t,f,UUID.randomUUID(),Set.of(),Set.of(p)),UUID.randomUUID(),p,r,w,now).outcome()==AppointmentRequestIntake.Outcome.DENIED_NOT_DISCLOSED);n++;check(s.prepare(c,UUID.randomUUID(),p,r,w,now.plusSeconds(3600)).outcome()==AppointmentRequestIntake.Outcome.INVALID_REQUEST);n++;check(s.prepare(null,UUID.randomUUID(),p,r,w,now).draft()==null);n++;System.out.println("PASS "+n+" request intake assertions");}static void check(boolean b){if(!b)throw new AssertionError();}}
